INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (10, 319, "", 1, "", 2, 24016, 0, 20001, 0, 0);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (10, 320, "", 20, "", 2, 23001, 0, 20001, 0, 0);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 321, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 1, "リリ", 2, 24001, 125801, 40011, 0, 1);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (2, 322, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 1, "クリア", 2, 24001, 126001, 40011, 0, 1);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (3, 323, "んーと。\nこれ、あげる。\nはい", 1, "プレシア", 2, 24001, 126101, 40011, 0, 1);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (4, 324, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 1, "リリ", 2, 24001, 125801, 40011, 0, 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (5, 325, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 1, "クリア", 2, 24001, 126001, 40011, 0, 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (6, 326, "お兄。\nきてくれて、うれしい", 1, "プレシア", 2, 24001, 126101, 40011, 0, 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 327, "", 100, "", 8, 91002, 0, 80009, 532001, 0);
